python3 - << 'PY'
import gzip, csv
from collections import defaultdict
path = "data/erate_frn_status_fy2024.csv.gz"
with gzip.open(path, "rt", encoding="utf-8", errors="replace", newline="") as fh:
    rows = [{k:(v or "").strip() for k,v in r.items()} for r in csv.DictReader(fh)]
by = defaultdict(dict)
for r in rows:
    by[r["funding_request_number"]][r["form_version"]] = r

def fnum(x):
    try: return float(x)
    except: return None

# Find interesting FRNs:
# 1. QK7 with current commitment 0 but original > 0 (status says funded-like but money is 0)
# 2. ZP2 with current commitment 0 but pre-discount still positive (status zeroed money, pre remains)
# 3. VD4 similar
# 4. VR9 with commitment reduced
# 5. only-original (undecided candidate)
# 6. QK7 with commitment increased

cands = {"qk7_zero": None, "vr9_zero": None, "zp2_typical": None, "vd4_typical": None,
         "qk7_reduced": None, "qk7_increased": None, "vr9_typical": None, "only_orig": None,
         "zp2_pre_changed": None, "vd4_pre_changed": None, "qk7_positive": None}

for frn,v in by.items():
    o,c = v.get("Original"), v.get("Current")
    if c is None and o is not None and cands["only_orig"] is None:
        cands["only_orig"] = frn
        continue
    if not c: continue
    st = c["form_471_frn_status_name"]
    fc = fnum(c["funding_commitment_request"])
    fo = fnum(o["funding_commitment_request"]) if o else None
    pc = fnum(c["total_pre_discount_costs"])
    if st=="QK7" and fc==0 and fo and fo>0 and cands["qk7_zero"] is None:
        cands["qk7_zero"] = frn
    if st=="VR9" and fc==0 and cands["vr9_zero"] is None:
        cands["vr9_zero"] = frn
    if st=="ZP2" and fc==0 and pc and pc>0 and fo and fo>0 and cands["zp2_typical"] is None:
        cands["zp2_typical"] = frn
    if st=="VD4" and fc==0 and pc and pc>0 and fo and fo>0 and cands["vd4_typical"] is None:
        cands["vd4_typical"] = frn
    if st=="QK7" and fo and fc and 0<fc<fo*0.5 and cands["qk7_reduced"] is None:
        cands["qk7_reduced"] = frn
    if st=="QK7" and fo and fc and fc>fo*1.5 and cands["qk7_increased"] is None:
        cands["qk7_increased"] = frn
    if st=="VR9" and fo and fc and fc>0 and abs(fc-fo)<1e-6 and cands["vr9_typical"] is None:
        cands["vr9_typical"] = frn
    if st=="QK7" and fo and fc and abs(fc-fo)<1e-6 and fc>1000 and cands["qk7_positive"] is None:
        cands["qk7_positive"] = frn
    if st=="ZP2" and o and o["total_pre_discount_costs"]!=c["total_pre_discount_costs"] and cands["zp2_pre_changed"] is None:
        cands["zp2_pre_changed"] = frn
    if st=="VD4" and o and o["total_pre_discount_costs"]!=c["total_pre_discount_costs"] and cands["vd4_pre_changed"] is None:
        cands["vd4_pre_changed"] = frn

for k,v in cands.items():
    print(k, v)
    if not v: continue
    rec = by[v]
    for ver,row in rec.items():
        print(" ", ver, {kk: row[kk] for kk in ["form_471_frn_status_name","funding_commitment_request","total_pre_discount_costs","dis_pct","months_of_service","wave_sequence_number","pending_reason","appeal_wave_number","ben"]})
